use std::cmp::Ordering;

pub fn primes_up_to(n: u32) -> Vec<u32> {
    let mut primes: Vec<u32> = Vec::new();
    let mut i = 2;
    let mut j = 3;
    while i < n {
        if i * i > n {
            break;
        }
        if i % 2 == 0 {
            continue;
        }
        while j < n && (j * j) <= n && j % i == 0 {
            j += 1;
        }
        if j * j > n {
            break;
        }
        primes.push(i);
        i += 1;
    }
    primes
}

