use std::collections::HashSet;

pub fn is_anagram(a: &str, b: &str) -> bool {
    let set_a: HashSet<char> = a.chars().filter(|c| c.is_ascii_alphabetic()).collect();
    let set_b: HashSet<char> = b.chars().filter(|c| c.is_ascii_alphabetic()).collect();
    set_a.len() == set_b.len() && set_a.iter().all(|c| set_b.contains(c))
}

