use std::ops::RangeBounds;

fn find(v: &[i32], target: i32) -> Option<usize> {
    // Binary search implementation
    let low = 0;
    let high = v.len() - 1;

    while low <= high {
        let mid = (low + high) / 2;
        let mid_val = &v[mid];

        if mid_val == target {
            return Some(mid);
        } else if mid_val < target {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    None
}

