pub fn collatz_steps(n: u64) -> u32 {
    if n < 1 {
        panic!("Input n must be at least 1");
    }
    let mut steps = 0;
    let mut current = n;
    while current > 1 {
        if current % 2 == 0 {
            current = current / 2;
            steps += 1;
        } else {
            current = 3 * current + 1;
            steps += 1;
        }
    }
    steps
}

