pub fn median(v: &[f64]) -> Option<f64> {
    if v.is_empty() {
        return None;
    }

    let mut left_idx = 0;
    let mut right_idx = v.len() - 1;

    while left_idx < right_idx {
        let mid = (left_idx + right_idx) / 2;
        if mid < 0 || mid > v.len() {
            return None;
        }

        if v[mid] < v[left_idx] {
            left_idx = mid;
        } else {
            right_idx = mid;
        }
    }

    if left_idx == right_idx {
        return v[left_idx];
    }

    let mid = (left_idx + right_idx) / 2;
    let left = v[left_idx];
    let right = v[right_idx];

    if left < right {
        return Some((left + right) / 2.0);
    }

    Some(v[mid])
}

