use std::str::FromStr;

pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if s.is_empty() {
        return None;
    }

    let mut chars = s.chars().collect::<Vec<char>>();
    let mut r = 0;
    let mut g = 0;
    let mut b = 0;

    for c in chars {
        if c.is_ascii_digit() {
            let digit = c.to_digit(16).ok_or_else(|| "Invalid hex character".into())?;
            r = (digit * 16) - '0';
            g = (digit * 16) - 'g';
            b = (digit * 16) - 'b';
        } else {
            return None;
        }
    }

    Some((r, g, b))
}

