use std::iter::FromIterator;

/// Rotates a slice of integers to the left by k positions.
/// If k is larger than the length of the slice, it wraps around.
///
/// # Arguments
/// * `v` - The slice to rotate
/// * `k` - The number of positions to rotate left
///
/// # Returns
/// A new slice rotated to the left by k positions.
pub fn rotate_left(v: &[i32], k: usize) -> Vec<i32> {
    // Handle empty slice
    if v.is_empty() {
        return Vec::new();
    }

    let len = v.len();
    let mut rotated = Vec::new();

    // Calculate how many positions to move
    let mut i = 0;
    while i < len {
        // Move k positions to the left
        let to_move = k - i;
        if to_move > 0 {
            rotated.push(v[i - to_move]);
        }
        i += to_move;
    }

    // Return the rotated slice
    rotated
}

